 "content": "from collections import Counter


def transform(grid):
    """Restore masked cells in a periodic horizontal field with a left wedge shift."""
    h, w = len(grid), len(grid[0])
    # Cells on/above the main diagonal belong to the unshifted horizontal field.
    by_col = []
    for c in range(w):
        observed = [grid[r][c] for r in range(min(h, c + 1)) if grid[r][c] != 0]
        if not observed:
            raise ValueError(f"cannot infer base value for column {c}")
        by_col.append(Counter(observed).most_common(1)[0][0])

    # Find the smallest period consistent with all observed column representatives.
    period = next(
        (p for p in range(1, w + 1)
         if all(by_col[c] == by_col[c % p] for c in range(p, w))),
        w,
    )
    base = by_col[:period]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = base[(c + (1 if c < r else 0)) % period]
    return out
